data.input:
const root="/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild";
const cmds=[
["AJCR connected all compact","horizon search --name connected --lib Algebraic-Jacobian-Challenge-Rebuild --limit 300 --json 2>/dev/null | jq '[.[] | {name,signature,file,line}]'",root],
["AJCR projective relevant compact","horizon search --name isProjective --lib Algebraic-Jacobian-Challenge-Rebuild --limit 300 --json 2>/dev/null | jq '[.[] | select(.signature|test(\"Pic0FiniteStage|GrpObj|RepresentableBy|LocallyOfFiniteType|QuasiCompact|FiniteInAffine|IsImmersion\";\"i\")) | {name,signature,file,line}]'",root],
["AJCR hquasi all compact","horizon search --name IsHQuasiProjective --lib Algebraic-Jacobian-Challenge-Rebuild --limit 300 --json 2>/dev/null | jq '[.[] | {name,signature,file,line}]'",root],
["AJCR finite affine all compact","horizon search --name finiteInAffine --lib Algebraic-Jacobian-Challenge-Rebuild --limit 300 --json 2>/dev/null | jq '[.[] | {name,signature,file,line}]'",root]
];
const rs=await Promise.all(cmds.map(async ([l,c,w])=>{const r=await tools.exec_command({cmd:c,workdir:w,yield_time_ms:30000,max_output_tokens:30000});return `## ${l}\n${r.output}\n(exit ${r.exit_code})`}));
rs.forEach(text);

