const root="/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild";
const cmds=[
["files finite representation","rg --files AlgebraicJacobian/Picard | rg 'Pic0FiniteStage.*(Represent|Glu|BaseChange|Diagram)'",root],
["representation declarations finite","rg -n -g 'Pic0FiniteStage*.lean' '^(noncomputable )?(def|theorem|lemma|instance).*Represent|RepresentableBy|gluedOver' AlgebraicJacobian/Picard",root],
["global iso names finite indexed","horizon search --name Pic0FiniteStage --lib Algebraic-Jacobian-Challenge-Rebuild --limit 500 --json 2>/dev/null | jq '[.[] | select((.name|test(\"[Ii]so|[Cc]ompar|[Bb]aseChange|[Rr]epresent\")) or (.signature|test(\"≅|RepresentableBy\"))) | {name,signature,file,line}]'",root],
["JacobianData structure fields","rg -n -A60 -B5 'structure JacobianData' AlgebraicJacobian/Picard AlgebraicJacobian/Tangent",root],
["JacobianData property declarations","rg -n -g '*.lean' 'JacobianData.*(FiniteInAffine|IsProjective|IsHQuasiProjective|ConnectedSpace|IrreducibleSpace)|(?:FiniteInAffine|IsProjective|IsHQuasiProjective|ConnectedSpace|IrreducibleSpace).*JacobianData' AlgebraicJacobian",root]
];
